-- Execute no SQL Editor do Supabase
create table if not exists public.produtos(id bigint generated by default as identity primary key,nome text not null,descricao text,preco numeric(10,2) not null default 0,categoria text not null default 'Outros',imagem text,imagem_url text,destaque boolean not null default false,ativo boolean not null default true,ordem integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.pedidos(id bigint generated by default as identity primary key,cliente_nome text not null,telefone text,tipo_pedido text not null default 'Entrega',endereco text,complemento text,pagamento text,observacao text,itens jsonb not null default '[]'::jsonb,subtotal numeric(10,2) not null default 0,taxa_entrega numeric(10,2) not null default 0,total numeric(10,2) not null default 0,status text not null default 'novo',created_at timestamptz not null default now());
alter table public.produtos enable row level security;alter table public.pedidos enable row level security;
drop policy if exists "Cardapio publico - leitura" on public.produtos;create policy "Cardapio publico - leitura" on public.produtos for select to anon,authenticated using(ativo=true);
drop policy if exists "Checkout publico - criar pedido" on public.pedidos;create policy "Checkout publico - criar pedido" on public.pedidos for insert to anon,authenticated with check(true);
-- Crie um bucket PUBLIC chamado produtos e coloque os caminhos em produtos.imagem.
